if (object != 0 && (object->list_flags & BOD_FLAG_LINKED) != 0) {
    BodList* list = &g_game->active_bod_list;
    DWORD flags = object->list_flags;
    if ((flags & BOD_FLAG_LINKED) == 0) {
        report_errorf("List remove");
    } else if ((flags & BOD_FLAG_NEXT_UPDATE_GUARD) != 0) {
        report_errorf("List remove NEXTBOD");
    } else {
        BodNode* next = object->list_next;
        if (next != 0)
            next->list_prev = object->list_prev;
        BodNode* prev = object->list_prev;
        if (prev != 0)
            prev->list_next = object->list_next;
        else
            list->first = object->list_next;
        object->list_next = list->free_top;
        list->free_top = object;
        object->list_flags &= ~BOD_FLAG_LINKED;
    }
}

